633:async function handleCompaction(request, payload, apiPath, rawBody) {
634:  const config = loadConfig();
635:  const model = findModel(payload.model, config);
636:  if (!model) {
637:    return forwardNative(request, apiPath, rawBody);
638:  }
639:  const provider = providerFor(model, config);
640:  if (!provider) {
641:    return json({ error: { message: "No provider configured for " + model.alias } }, 500);
642:  }
643:  const bodyForBytes = JSON.stringify({
644:    model: model.alias,
645:    input: payload.input || [],
646:  });
647:  const requestBytes = Buffer.byteLength(bodyForBytes, "utf8");
648:  const result = await summarize({
649:    payload,
650:    model,
651:    provider,
652:    requestBytes,
653:    signal: request.signal,
654:  });
655:  if (!result.ok) {
656:    return json(result.payload, result.status);
657:  }
658:  const inputs = Array.isArray(payload.input) ? payload.input : [];
659:  const compactionV2 =
660:    inputs.length > 0 && inputs[inputs.length - 1]?.type === "compaction_trigger";
661:  if (compactionV2) {
662:    if (payload.stream === false) {
663:      const item = {
664:        type: "compaction",
665:        id: newId("cmp"),
666:        encrypted_content: encodeSummary(result.summary),
667:      };
668:      return json(compactionSnapshot(payload.model, item));
669:    }
670:    return new Response(writeCompactionSseEvents(payload.model, result.summary), {
671:      headers: SSE_HEADERS,
672:    });
673:  }
674:  return json({ output: compactOutputV1(result.input, result.summary) });
675:}
