function bunFallback(name) {
  try {
    const fn = globalThis.Bun && globalThis.Bun[name];
    return typeof fn === "function" ? fn : undefined;
  } catch {
    return undefined;
  }
}

function decompressOne(bytes, encoding) {
  const enc = String(encoding || "").trim().toLowerCase().split(";", 1)[0].trim();
  if (!enc || enc === "identity" || enc === "chunked") return bytes;
  const input = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
  if (enc === "zstd" || enc === "zst") {
    const fn = typeof zlib.zstdDecompressSync === "function" ? zlib.zstdDecompressSync : bunFallback("zstdDecompressSync");
    if (!fn) throw new Error("zstd unsupported");
    return Buffer.from(fn(input));
  }
  if (enc === "gzip" || enc === "x-gzip" || enc === "gz") {
    const gunzip = typeof zlib.gunzipSync === "function" ? zlib.gunzipSync : bunFallback("gunzipSync");
    try {
      return Buffer.from(gunzip(input));
    } catch {
      if (typeof zlib.unzipSync === "function") return Buffer.from(zlib.unzipSync(input));
      throw new Error("gzip decode failed");
    }
  }
  if (enc === "deflate" || enc === "zlib") {
    const inflate = typeof zlib.inflateSync === "function" ? zlib.inflateSync : bunFallback("inflateSync");
    try {
      return Buffer.from(inflate(input));
    } catch {
      try {
        if (typeof zlib.inflateRawSync === "function") return Buffer.from(zlib.inflateRawSync(input));
      } catch {}
      if (typeof zlib.unzipSync === "function") return Buffer.from(zlib.unzipSync(input));
      throw new Error("deflate decode failed");
    }
  }
  if (enc === "br" || enc === "brotli") {
    if (typeof zlib.brotliDecompressSync !== "function") throw new Error("br unsupported");
    return Buffer.from(zlib.brotliDecompressSync(input));
  }
  return bytes;
}

function decodeRequestBody(raw, contentEncoding) {
  let bytes = Buffer.isBuffer(raw)
    ? raw
    : raw instanceof ArrayBuffer
      ? Buffer.from(new Uint8Array(raw))
      : Buffer.from(raw || []);
  if (bytes.length === 0) return bytes;
  const header = String(contentEncoding || "");
  const tokens = header
    .split(",")
    .map((s) => String(s).trim().split(";", 1)[0].trim().toLowerCase())
    .filter(Boolean);
  const hasEncoding = tokens.some((t) => t && t !== "identity");
  if (hasEncoding) {
    for (let i = tokens.length - 1; i >= 0; i -= 1) {
      const enc = tokens[i];
      if (!enc || enc === "identity" || enc === "chunked") continue;
      try {
        bytes = Buffer.from(decompressOne(bytes, enc));
      } catch {
        break;
      }
    }
    return bytes;
  }
  if (bytes.length >= 4 && bytes[0] === 0x28 && bytes[1] === 0xb5 && bytes[2] === 0x2f && bytes[3] === 0xfd) {
    try {
      return Buffer.from(decompressOne(bytes, "zstd"));
    } catch {
      return bytes;
    }
  }
  if (bytes.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b) {
    try {
      return Buffer.from(decompressOne(bytes, "gzip"));
    } catch {
      return bytes;
    }
  }
  return bytes;
}

