import { tmpdir } from "node:os";
import path from "node:path";
import * as zlib from "node:zlib";
import { createMockProvider } from "./smoke/mock-provider.mjs";
const mock = createMockProvider();
const dir = mkdtempSync(path.join(tmpdir(), "codextras-zstd-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"mock",type:"openai-chat",baseUrl:"http://127.0.0.1:"+mock.port,apiKeyEnv:"CODEXTRAS_TEST_KEY",quirks:{efforts:{low:"low",high:"high",max:"max"}}}],models:[{alias:"test-model",provider:"mock",upstreamModel:"mock-upstream",efforts:["high"],defaultEffort:"high",inputModalities:["text"]}]}));
process.env.CODEXTRAS_TEST_KEY="sk-test";
process.env.CODEXTRAS_CONFIG=configPath;
const { createServer } = await import("./src/server.mjs");
const { loadConfig } = await import("./src/config.mjs");
const secret="s3cr3t";
const server = createServer(loadConfig(), secret);
const base=`http://127.0.0.1:${server.port}/_codextras/${secret}`;
function user(t){return {type:"message",role:"user",content:[{type:"input_text",text:t}]};}
async function trial(name, bodyObj, headers) {
  const body = Buffer.from(JSON.stringify(bodyObj));
  let payload = body;
  let h = {"Content-Type":"application/json", ...headers};
  if (headers["Content-Encoding"]==="zstd") payload = Buffer.from(Bun.zstdCompressSync(body));
  if (headers["Content-Encoding"]==="gzip") payload = Buffer.from(Bun.gzipSync(body));
  if (headers["Content-Encoding"]==="deflate") payload = zlib.deflateSync(body);
  if (headers["Content-Encoding"]==="br") payload = zlib.brotliCompressSync(body);
  if (headers["__raw_zstd_noheader"]) { payload = Buffer.from(Bun.zstdCompressSync(body)); delete h["__raw_zstd_noheader"]; }
  if (headers["__raw_gzip_noheader"]) { payload = Buffer.from(Bun.gzipSync(body)); delete h["__raw_gzip_noheader"]; }
  const res = await fetch(base+"/v1/responses", {method:"POST", headers:h, body: payload});
  const txt = await res.text();
  let ok=false;
  try { const j=JSON.parse(txt); ok = j.output?.some(i=>i.type==="message"); } catch {}
  console.log(`${name}: status=${res.status} ok=${ok} len=${txt.length} prefix=${txt.slice(0,120).replace(/\n/g,"|")}`);
  return res.status;
}
await trial("plain", {model:"test-model",input:[user("hi")],stream:false}, {});
await trial("zstd+header", {model:"test-model",input:[user("hi")],stream:false}, {"Content-Encoding":"zstd"});
await trial("zstd-noheader-sniff", {model:"test-model",input:[user("hi")],stream:false}, {"__raw_zstd_noheader":1});
await trial("gzip+header", {model:"test-model",input:[user("hi")],stream:false}, {"Content-Encoding":"gzip"});
await trial("gzip-noheader-sniff", {model:"test-model",input:[user("hi")],stream:false}, {"__raw_gzip_noheader":1});
await trial("deflate+header", {model:"test-model",input:[user("hi")],stream:false}, {"Content-Encoding":"deflate"});
await trial("br+header", {model:"test-model",input:[user("hi")],stream:false}, {"Content-Encoding":"br"});
await trial("zstd-stream", {model:"test-model",input:[user("hi")],stream:true}, {"Content-Encoding":"zstd"});
